import re

pools = {
    'pool1': re.compile('.*.example.com'),
    'pool2': re.compile('www.domain.org')
}

backends = ['www.backend1.com', 'www.backend2.com']

def get_backend(request):
    host = request.hostname

    for pool_name, pattern in pools.items():
        if pattern.match(host):
            idx = list(pools.keys()).index(pool_name)
            return backends[idx]

    return None

